    jsonb_build_object('number',11, 'answer',E'nothing special'),
    jsonb_build_object('number',12, 'answer',E'something cold'),
    jsonb_build_object('number',13, 'answer',E'anything hot'),
    jsonb_build_object('number',14, 'answer',E'something exciting'),
    jsonb_build_object('number',15, 'answer',E'something cold'),
